-- RLS — service role has full access
ALTER TABLE onchain_signals               ENABLE ROW LEVEL SECURITY;
ALTER TABLE signal_strategy_confirmations ENABLE ROW LEVEL SECURITY;
ALTER TABLE signal_executions             ENABLE ROW LEVEL SECURITY;
ALTER TABLE market_data_snapshots         ENABLE ROW LEVEL SECURITY;
ALTER TABLE signal_thresholds             ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Service role full access on onchain_signals"
  ON onchain_signals FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY "Service role full access on signal_strategy_confirmations"
  ON signal_strategy_confirmations FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY "Service role full access on signal_executions"
  ON signal_executions FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY "Service role full access on market_data_snapshots"
  ON market_data_snapshots FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY "Service role full access on signal_thresholds"
  ON signal_thresholds FOR ALL TO service_role USING (true) WITH CHECK (true);
